…-   목적: 주문 이벤트에서 상품별 주문수/수량을 집계해 카프카 토픽(product.counts)으로 내보냄.
    Redis 업데이트는 뒤의 컨슈머가 담당(ZINCRBY).

```java
@Configuration
public class StreamsTopology {

  @Bean
  public KStream<String, String> kStream(StreamsBuilder b) {
    KStream<String, String> raw = b.stream("order.events",
      Consumed.with(Serdes.String(), Serdes.String()));

    // 1) ORDER_CREATED만 추출
    KStream<String, OrderCreated> created = raw
      .mapValues(json -> parse(json))                 // JSON → POJO
      .filter((k, e) -> "ORDER_CREATED".equals(e.type()));

    // 2) productId 단위로 수량 증가 이벤트로 변환 (여러 item → fan-out)
    KStream<String, Long> productIncr = created.flatMap((key, ev) -> {
      List<KeyValue<String, Long>> out = new ArrayList<>();
      for (Item it : ev.items()) {
        out.add(new KeyValue<>(it.productId(), (long) it.quantity()));
      }
      return out;
    });

    // 3) 집계 (KTable: 누계 카운트)
    KTable<String, Long> counts = productIncr
      .groupByKey(Grouped.with(Serdes.String(), Serdes.Long()))
      .reduce(Long::sum); // materialized store 자동

    // 4) 변경 스트림을 토픽으로 내보내기 → Redis Updater가 반영
    counts.toStream().to("product.counts",
      Produced.with(Serdes.String(), Serdes.Long()));

    return raw; // bean 반환 용도
  }

  private OrderCreated parse(String json) {
    try { return new ObjectMapper().readValue(json, OrderCreated.class); }
    catch (Exception e) { throw new RuntimeException(e); }
  }
}
```

