사용자가 지정한 영역을 실시간으로 표시하고 이를 퍼센트 좌표로 변환하는 구조

```javascript
var $dragBox=null, dragState={active:false, startX:0, startY:0, imgRect:null};

function bindDrag(){
  $preview.off('.drag');
  if($('#dragMode').val() !== 'on') return;

  $preview.on('mousedown.drag', 'img', function(e){
    e.preventDefault();
    const rect = this.getBoundingClientRect();
    dragState = { active:true, startX:e.clientX, startY:e.clientY, imgRect:rect };
    $dragBox = $('<div class="drag-box"/>').appendTo($preview)
      .css({ left:(e.clientX-rect.left)+'px', top:(e.clientY-rect.top)+'px' });

    $(window).on('mousemove.drag', onMove);
    $(window).on('mouseup.drag', onUp);
  });
}

function onMove(e){
  if(!dragState.active || !$dragBox) return;
  const r = dragState.imgRect;
  let x1 = Math.min(dragState.startX, e.clientX);
  let y1 = Math.min(dragState.startY, e.clientY);
  let x2 = Math.max(dragState.startX, e.clientX);
  let y2 = Math.max(dragState.startY, e.clientY);
  // 이미지 경계로 클램프
  x1=Math.max(r.left,Math.min(x1,r.right)); x2=Math.max(r.left,Math.min(x2,r.right));
  y1=Math.max(r.top, Math.min(y1,r.bottom)); y2=Math.max(r.top, Math.min(y2,r.bottom));
  $dragBox.css({ left:(x1-r.left)+'px', top:(y1-r.top)+'px', width:(x2-x1)+'px', height:(y2-y1)+'px' });
}

function onUp(){
  $(window).off('mousemove.drag mouseup.drag');
  if(!dragState.active) return cleanupDrag();
  const r = dragState.imgRect, box = $dragBox[0].getBoundingClientRect();
  cleanupDrag();
  if(box.width < 5 || box.height < 5) return; // 너무 작으면 취소

  // px → % 변환
  const leftPct = ((box.left - r.left) / r.width) * 100;
  const topPct  = ((box.top  - r.top ) / r.height)* 100;
  const wPct    = ( box.width / r.width ) * 100;
  const hPct    = ( box.height/ r.height)* 100;

  hotspots.push({ id:uid(), mode:'percent', left:leftPct, top:topPct, width:wPct, height:hPct, href:'https://', label:'버튼'+(hotspots.length+1) });
  renderRows(); renderPreview();
}
function cleanupDrag(){ dragState.active=false; dragState.imgRect=null; $dragBox && $dragBox.remove(); $dragBox=null; }
```

