public class ProductRankingEventListener {

    private final ObjectMapper objectMapper;
    private final ProductRankingService productRankingService;

    @EventListener
    public void handleOrderCompleted(MockKafkaEvent event) {
        if (!"ORDER_COMPLETED".equals(event.eventType())) return;

        try {
            OrderCompletedEvent message =
                objectMapper.readValue(event.payload(), OrderCompletedEvent.class);

            message.items().forEach(item ->
