```sql
SET SERVEROUTPUT ON;

DECLARE
    -- 1) 테이블 리스트 타입 (이게 실제론 필요)
    TYPE t_table_list IS TABLE OF VARCHAR2(128);

    -- 2) 대상 테이블 목록
    v_tables t_table_list := t_table_list(
        '테이블 1',
        '테이블 2',
        '테이블 3'
    );

    -- 3) TRUNCATE / DROP 모드
    v_mode VARCHAR2(20) := 'TRUNCATE';  -- 또는 'DROP'

    -- 4) 성공/실패 로그용 컬렉션
    TYPE t_log IS TABLE OF VARCHAR2(4000);
    v_success_list t_log := t_log();
    v_fail_list    t_log := t_log();

    v_sql        VARCHAR2(4000);
    v_start_time DATE := SYSDATE;
    v_end_time   DATE;
BEGIN
    -- 시작 로그
    ...

    FOR i IN 1 .. v_tables.COUNT LOOP
        BEGIN
            -- 모드에 따라 SQL 생성
            IF v_mode = 'TRUNCATE' THEN
                v_sql := 'TRUNCATE TABLE ' || v_tables(i);
            ELSE
                v_sql := 'DROP TABLE ' || v_tables(i) || ' CASCADE CONSTRAINTS';
            END IF;

            EXECUTE IMMEDIATE v_sql;          -- ★ 실제 삭제/비우기 실행

            -- 성공 시 목록에 추가
            v_success_list.EXTEND;
            v_success_list(v_success_list.COUNT) := v_tables(i);

            DBMS_OUTPUT.PUT_LINE('SUCCESS: ' || v_sql);

        EXCEPTION
            WHEN OTHERS THEN
                -- 실패 시 실패 리스트에 테이블명 + 에러 메시지 저장
                v_fail_list.EXTEND;
                v_fail_list(v_fail_list.COUNT) :=
                    v_tables(i) || ' (' || SQLERRM || ')';

